package za.ac.cput.domain; import jakarta.persistence.*; @Entity public class Vehicle{@Id @GeneratedValue(strategy=GenerationType.UUID) private String vehicleId;private String licensePlate,make,model,color;private int year;private double mileage,dailyRate,weeklyRate;@Enumerated(EnumType.STRING) private VehicleStatus status;protected Vehicle(){} private Vehicle(Builder b){vehicleId=b.vehicleId;licensePlate=b.licensePlate;make=b.make;model=b.model;year=b.year;color=b.color;mileage=b.mileage;dailyRate=b.dailyRate;weeklyRate=b.weeklyRate;status=b.status;} public String getVehicleId(){return vehicleId;} public String getLicensePlate(){return licensePlate;} public String getMake(){return make;} public String getModel(){return model;} public int getYear(){return year;} public String getColor(){return color;} public double getMileage(){return mileage;} public double getDailyRate(){return dailyRate;} public double getWeeklyRate(){return weeklyRate;} public VehicleStatus getStatus(){return status;} public static class Builder{private String vehicleId,licensePlate,make,model,color;private int year;private double mileage,dailyRate,weeklyRate;private VehicleStatus status;public Builder setVehicleId(String v){vehicleId=v;return this;}public Builder setLicensePlate(String v){licensePlate=v;return this;}public Builder setMake(String v){make=v;return this;}public Builder setModel(String v){model=v;return this;}public Builder setYear(int v){year=v;return this;}public Builder setColor(String v){color=v;return this;}public Builder setMileage(double v){mileage=v;return this;}public Builder setDailyRate(double v){dailyRate=v;return this;}public Builder setWeeklyRate(double v){weeklyRate=v;return this;}public Builder setStatus(VehicleStatus v){status=v;return this;}public Builder copy(Vehicle x){vehicleId=x.vehicleId;licensePlate=x.licensePlate;make=x.make;model=x.model;year=x.year;color=x.color;mileage=x.mileage;dailyRate=x.dailyRate;weeklyRate=x.weeklyRate;status=x.status;return this;}public Vehicle build(){return new Vehicle(this);}}}